import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import DatePicker, { registerLocale } from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import es from 'date-fns/locale/es';
import "../Estilos/Reservas.css";
import jwt_decode from 'jwt-decode';  // Asegúrate de tener esta librería instalada

registerLocale('es', es);

function ReservayEquipo() {
  const navigate = useNavigate(); 
  const obtenerProximaFechaHabil = () => {
    const hoy = new Date();
    const dia = hoy.getDay(); 

    if (dia === 6) { 
      hoy.setDate(hoy.getDate() + 2); 
    } else if (dia === 0) { 
      hoy.setDate(hoy.getDate() + 1); 
    }

    return hoy;
  };

  const calcularFechaMaxima = (fechaMinima) => {
    const fechaMax = new Date(fechaMinima);
  
    const mesActual = fechaMinima.getMonth();
    const semestreActual = Math.floor(mesActual / 6) + 1;
  
    if (semestreActual === 1) {
      fechaMax.setFullYear(fechaMinima.getFullYear(), 5, 30); 
    } else {
      fechaMax.setFullYear(fechaMinima.getFullYear(), 11, 31); 
    }
  
    const dia = fechaMax.getDay();
    if (dia === 6) { // Sábado
      fechaMax.setDate(fechaMax.getDate() - 1); 
    } else if (dia === 0) { // Domingo
      fechaMax.setDate(fechaMax.getDate() - 2); 
    }
  
    return fechaMax;
  };
  
  const fechaMinima = obtenerProximaFechaHabil();
  const fechaMaxima = calcularFechaMaxima(fechaMinima);
  const errorRef = useRef(null); 
  const [disp, setDis] = useState(null);
  const [selectedDate, setSelectedDate] = useState(obtenerProximaFechaHabil());
  const [time, setTime] = useState('');
  const [error, setError] = useState(null);
  const [cancha, setCancha] = useState('');
  const [canchaTipo, setCanchaTipo] = useState('');
  const [equipo, setEquipo] = useState('');
  const [canchasReservadas, setCanchasReservadas] = useState([]);
  const [equiposReservados, setEquiposReservados] = useState([]);
  const [canchas, setCanchas] = useState([]);
  const [equipos, setEquipos] = useState([]);
  const [horasNoDisponibles, setHorasNoDisponibles] = useState([]);
  const [isSanctioned, setIsSanctioned] = useState(false);
  const [sancionEndDate, setSancionEndDate] = useState(null);

  const setErrorWithTimeout = (message) => {
    setError(message);
    setTimeout(() => {
      setError("");
    }, 3000);
  };

  useEffect(() => {
    if (error && errorRef.current) {
      errorRef.current.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  }, [error]); 

  useEffect(() => {
    const fetchCanchasYEquipos = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        setErrorWithTimeout('No se encontró el token de autenticación.');
        return;
      }
    
      try {
        const response = await fetch('http://localhost:5000/api/canchas_equipo', {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`,
          },
        });
    
        if (response.ok) {
          const data = await response.json();
          setCanchas(data.canchas_disponibles);
          setEquipos(data.equipos_disponibles);
        } else {
          const errorData = await response.json();
          setErrorWithTimeout(errorData.error || 'Error al obtener los datos.');
        }
      } catch (error) {
        setErrorWithTimeout('Error de red: ' + error.message);
      }
    };

    fetchCanchasYEquipos();
  }, []);

  useEffect(() => {
    const verificarSancion = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        setErrorWithTimeout('No se encontró el token de autenticación.');
        return;
      }

      try {
        const decodedToken = jwt_decode(token);  // Decodificamos el token para obtener el correo
        const email = decodedToken.email;

        const response = await fetch(`http://localhost:5000/api/usuarios/${email}/sancion-activa`, {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          }
        });

        const data = await response.json();

        if (data.isSanctioned) {
          setIsSanctioned(true);
          setSancionEndDate(data.fechaFinSancion);
        } else {
          setIsSanctioned(false);
        }
      } catch (error) {
        setErrorWithTimeout('Error al verificar sanción.');
      }
    };

    verificarSancion();
  }, []);

  useEffect(() => {
    const fetchCanchasYEquiposReservados = async () => {
      try {
        const body = {
          fecha: selectedDate.toLocaleDateString('es-CL'), // Formato YYYY-MM-DD
          hora: null,
        };
        if (time) {
          body.hora = time;
        }

        const response = await fetch('http://localhost:5000/api/equipo_and_canchas', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${localStorage.getItem("token")}`
          },
          body: JSON.stringify(body)
        });

        if (response.ok) {
          const data = await response.json();
          if (time) {
            setCanchasReservadas(data.canchas_reservadas);
            setEquiposReservados(data.equipos_reservados);
          } else {
            setHorasNoDisponibles(data.horas_no_disponibles);
          }
        } else {
          setErrorWithTimeout('Error en la solicitud:', response.statusText);
        }
      } catch (error) {
        setErrorWithTimeout('Error en la solicitud:', error);
      }
    };

    if(selectedDate) {
      fetchCanchasYEquiposReservados();
    }
  }, [selectedDate, time]);

  useEffect(() => {
    const verificarReservas = async () => {
      const token = localStorage.getItem('token');
      const formData = {
        fecha: selectedDate.toLocaleDateString('es-CL'),
      };

      try {
        const response = await fetch('http://localhost:5000/api/verificar_reservas', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`,
          },
          body: JSON.stringify(formData),
        });

        if (response.ok) {
          setDis(true);
        } else if (response.status === 409) {
          const result = await response.json();
          setDis(false);
          setErrorWithTimeout(result.error);
        } else if (response.status === 410) {
          const result = await response.json();
          setDis(false);
          alert(result.error);
          navigate("/TuReservacion");
        }

      } catch (error) {
        setErrorWithTimeout('Error al conectar con el servidor.');
      }
    };

    if (selectedDate) {
      verificarReservas();
    }
  }, [selectedDate, navigate]);

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError(null);

    const token = localStorage.getItem('token');
    const formData = {
      fecha: selectedDate.toLocaleDateString('es-CL'),
      hora: time,
      cancha: cancha,
      equipo: equipo,
    };

    try {
      const response = await fetch('http://localhost:5000/api/reservas', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify(formData),
      });

      if (response.status === 201) {
        alert("Se ha reservado con éxito");
        navigate("/TuReservacion");
      } else if (response.status === 409) {
        const result = await response.json();
        setErrorWithTimeout(result.error);
      } else {
        setErrorWithTimeout('Ocurrió un error al realizar la reserva.');
      }
    } catch (error) {
      setErrorWithTimeout('Error al conectar con el servidor.');
    }
  };

  const generarOpcionesTiempo = () => {
    const opciones = [];
    for (let hora = 8; hora <= 18; hora++) {
      for (let minuto = 0; minuto < 60; minuto += 15) {
        const horaFormato = `${hora.toString().padStart(2, '0')}:${minuto.toString().padStart(2, '0')}`;
        opciones.push(horaFormato);
      }
    }
    return opciones;
  };

  return (
    <div className="container">
      <h2>Formulario de Reserva</h2>
      {isSanctioned && (
        <div className="alert alert-warning" role="alert">
          <p>Estás sancionado hasta: {new Date(sancionEndDate).toLocaleDateString()}</p>
        </div>
      )}
      <form onSubmit={handleSubmit}>
        <div>
          <label>Fecha</label>
          <DatePicker
            selected={selectedDate}
            onChange={(date) => setSelectedDate(date)}
            minDate={fechaMinima}
            maxDate={fechaMaxima}
            locale="es"
            dateFormat="dd/MM/yyyy"
            required
          />
        </div>
        <div>
          <label>Hora</label>
          <select onChange={(e) => setTime(e.target.value)} value={time} required>
            <option value="">Seleccione una hora</option>
            {generarOpcionesTiempo().map((hora) => (
              <option key={hora} value={hora}>{hora}</option>
            ))}
          </select>
        </div>
        <div>
          <label>Cancha</label>
          <select onChange={(e) => setCancha(e.target.value)} value={cancha} required>
            <option value="">Seleccione una cancha</option>
            {canchas.map((cancha) => (
              <option key={cancha._id} value={cancha._id}>{cancha.nombre}</option>
            ))}
          </select>
        </div>
        <div>
          <label>Equipo</label>
          <select onChange={(e) => setEquipo(e.target.value)} value={equipo} required>
            <option value="">Seleccione un equipo</option>
            {equipos.map((equipo) => (
              <option key={equipo._id} value={equipo._id}>{equipo.nombre}</option>
            ))}
          </select>
        </div>
        <div>
          <button type="submit" disabled={isSanctioned}>
            {isSanctioned ? 'No puedes reservar durante tu sanción' : 'Reservar'}
          </button>
        </div>
        {error && <div className="error" ref={errorRef}>{error}</div>}
      </form>
    </div>
  );
}

export default ReservayEquipo;
